import { Component } from '@angular/core';
import { Gallery } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';

@Component({
  selector: 'app-demo',
  imports: [Gallery, GalleryModule],
  template: `
    <gallery
        [style.--g-item-image-size]="imageSize"
        [items]="items"
        [itemSize]="itemSize"
        [itemsPerView]="itemsPerView"
        [snapAlign]="snapAlign"
        [forceSnap]="forceSnap"
        [resizeDebounceTime]="resizeDebounceTime"
        [loop]="loop"
        [orientation]="orientation"
        [scrollDuration]="scrollDuration"
        [scrollBehavior]="scrollBehavior"
        [disableScroll]="disableScroll"
        [disableMouseScroll]="disableMouseScroll">
        <img
            *galleryItemDef="let item"
            galleryImage
            [src]="item.src"
            [alt]="item.alt" />
        @if (nav) {
        <gallery-nav/>
        }

            @if (counter) {
        <gallery-counter [align]="counterAlign"/>
        }

            @if (thumbs) {
        <gallery-thumbs
            [style.--g-thumb-image-size]="thumbImageSize"
            [snapAlign]="thumbSnapAlign"
            [forceSnap]="thumbForceSnap"
            [itemsPerView]="thumbsPerView"
            [itemSize]="thumbSize"
            [thickness]="thickness"
            [disableScroll]="disableThumbScroll"
            [disableMouseScroll]="disableThumbMouseScroll"
            [position]="thumbPosition"
            [floating]="thumbFloating">
            <button *galleryItemDef="let item" galleryThumbClick>
                <img galleryImage [src]="item.thumb" [alt]="item.alt + '_thumb'"/>
            </button>
        </gallery-thumbs>
        }

            @if (debug) {
        <gallery-debug/>
        }
    </gallery>`,
})
export class DemoComponent {
  debug = true;
  thumbs = true;
  thumbPosition = 'bottom';
  loop = false;
  disableScroll = false;
  disableMouseScroll = false;
  itemSize = null;
  itemsPerView = 1;
  orientation = 'horizontal';
  snapAlign = 'center';
  forceSnap = false;
  scrollDuration = 468;
  thickness = 90;
  nav = true;
  imageSize = 'contain';
  thumbImageSize = 'cover';
  thumbsPerView = 5;
  thumbSize = 120;
  thumbSnapAlign = 'center';
  thumbForceSnap = false;
  disableThumbScroll = false;
  disableThumbMouseScroll = false;
  counterAlign = 'bottom';
  scrollBehavior = 'smooth';
  thumbFloating = false;
}

